create extension if not exists pgcrypto;
create type public.app_role as enum ('owner','manager','collector','viewer');
create type public.loan_status as enum ('draft','active','fully_paid','cancelled');
create type public.payment_status as enum ('pending','verified','rejected','reversed');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.organization_members(organization_id uuid not null references public.organizations,user_id uuid not null references auth.users,role public.app_role not null default 'viewer',status text not null default 'active',primary key(organization_id,user_id));
create table public.borrowers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,first_name text not null,last_name text not null,phone text,email text,address text,created_by uuid references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz);
create table public.loans(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,borrower_id uuid not null references public.borrowers,principal_centavos bigint not null check(principal_centavos>0),monthly_rate_basis_points integer not null check(monthly_rate_basis_points>=0),term_months integer not null check(term_months>0),total_centavos bigint not null,status public.loan_status not null default 'draft',terms_snapshot jsonb not null default '{}'::jsonb,created_by uuid references auth.users,created_at timestamptz not null default now());
create table public.installments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,loan_id uuid not null references public.loans,sequence integer not null,due_date date not null,principal_centavos bigint not null,interest_centavos bigint not null,scheduled_centavos bigint not null,unique(loan_id,sequence));
create table public.payments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,loan_id uuid not null references public.loans,amount_centavos bigint not null check(amount_centavos>0),received_at timestamptz not null,method text not null,reference text,status public.payment_status not null,client_operation_id uuid not null,device_id text not null,created_by uuid references auth.users,created_at timestamptz not null default now(),unique(organization_id,client_operation_id));
create table public.payment_allocations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,payment_id uuid not null references public.payments,installment_id uuid not null references public.installments,principal_centavos bigint not null default 0,interest_centavos bigint not null default 0,penalty_centavos bigint not null default 0,unique(payment_id,installment_id));
create table public.audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,actor_id uuid references auth.users,action text not null,record_type text not null,record_id uuid not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index borrowers_org_name_idx on public.borrowers(organization_id,last_name,first_name);create index installments_org_due_idx on public.installments(organization_id,due_date);create index payments_org_status_idx on public.payments(organization_id,status,received_at);
create or replace function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_members m where m.organization_id=org and m.user_id=auth.uid() and m.status='active')$$;
create or replace function public.has_org_role(org uuid, allowed_roles public.app_role[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.organization_members m where m.organization_id=org and m.user_id=auth.uid() and m.status='active' and m.role=any(allowed_roles))$$;
alter table public.organizations enable row level security;alter table public.organization_members enable row level security;alter table public.borrowers enable row level security;alter table public.loans enable row level security;alter table public.installments enable row level security;alter table public.payments enable row level security;alter table public.payment_allocations enable row level security;alter table public.audit_events enable row level security;
create policy members_read_organizations on public.organizations for select using(public.is_org_member(id));create policy owners_update_organizations on public.organizations for update using(public.has_org_role(id,array['owner']::public.app_role[])) with check(public.has_org_role(id,array['owner']::public.app_role[]));
create policy members_read_memberships on public.organization_members for select using(public.is_org_member(organization_id));create policy owners_add_memberships on public.organization_members for insert with check(public.has_org_role(organization_id,array['owner']::public.app_role[]));create policy owners_update_memberships on public.organization_members for update using(public.has_org_role(organization_id,array['owner']::public.app_role[])) with check(public.has_org_role(organization_id,array['owner']::public.app_role[]));
create policy members_read_borrowers on public.borrowers for select using(public.is_org_member(organization_id));create policy staff_add_borrowers on public.borrowers for insert with check(public.has_org_role(organization_id,array['owner','manager','collector']::public.app_role[]));create policy staff_update_borrowers on public.borrowers for update using(public.has_org_role(organization_id,array['owner','manager','collector']::public.app_role[])) with check(public.has_org_role(organization_id,array['owner','manager','collector']::public.app_role[]));
create policy members_read_loans on public.loans for select using(public.is_org_member(organization_id));create policy managers_add_loans on public.loans for insert with check(public.has_org_role(organization_id,array['owner','manager']::public.app_role[]));create policy managers_update_loans on public.loans for update using(public.has_org_role(organization_id,array['owner','manager']::public.app_role[])) with check(public.has_org_role(organization_id,array['owner','manager']::public.app_role[]));
create policy members_read_installments on public.installments for select using(public.is_org_member(organization_id));
create policy org_payments_read on public.payments for select using(public.is_org_member(organization_id));create policy org_allocations_read on public.payment_allocations for select using(public.is_org_member(organization_id));create policy org_audit_read on public.audit_events for select using(public.is_org_member(organization_id));
-- Financial writes intentionally have no client policy. A future atomic, idempotent RPC will post payments and allocations.
